 with h5py.File(p,'r') as f:
  if np.any(f['units/classification'][()]==b'good'): files.append(p)
counts={k:[] for k in ['all','noearly','responded','noearly_responded','regular_inclstim','regular_control']}
perf=[]; lr=[]
for p in files:
 with h5py.File(p,'r') as f:
  t=f['intervals/trials']; n=len(t['id']); early=t['early_lick'][()]==b'no early'; out=t['outcome'][()]; resp=out!=b'ignore'; aw=t['auto_water'][()]==0; fw=t['free_water'][()]==0
  power=t['photostim_power'][()]; control=np.array([(x==b'N/A') or (isinstance(x,float) and np.isnan(x)) for x in power])
  masks={'all':np.ones(n,bool),'noearly':early,'responded':resp,'noearly_responded':early&resp,'regular_inclstim':early&resp&aw&fw,'regular_control':early&resp&aw&fw&control}
  for k,m in masks.items(): counts[k].append(int(m.sum()))
  m=early&control
  perf.append(np.mean(out[m]==b'hit'))
