import glob,h5py,numpy as np,collections
c=collections.Counter(); examples=[]
for p in sorted(glob.glob('/app/data/sub-*/*.nwb')):
 with h5py.File(p,'r') as f:
  cls=f['units/classification'][()]
  if not np.any(cls==b'good'): continue
  n=f['units/is_good_trials'].shape[1]
  t=f['intervals/trials']; out=t['outcome'][:n]; inst=t['trial_instruction'][:n]
  go=f['acquisition/BehavioralEvents/go_start_times/timestamps'][:n]
  l=f['acquisition/BehavioralEvents/left_lick_times/timestamps'][()]; r=f['acquisition/BehavioralEvents/right_lick_times/timestamps'][()]
  for i,g in enumerate(go):
   li=np.searchsorted(l,g); ri=np.searchsorted(r,g); lt=l[li] if li<len(l) and l[li]<g+1.5 else np.inf; rt=r[ri] if ri<len(r) and r[ri]<g+1.5 else np.inf
   actual=b'left' if lt<rt else (b'right' if rt<lt else b'none')
   expected=inst[i] if out[i]==b'hit' else ((b'right' if inst[i]==b'left' else b'left') if out[i]==b'miss' else b'none')
   c[(out[i].decode(),expected.decode(),actual.decode())]+=1
   if actual!=expected and len(examples)<15: examples.append((p.split('/')[-1],i+1,out[i],inst[i],actual,lt-g,rt-g))
print('total',sum(c.values()),'match',sum(v for (o,e,a),v in c.items() if e==a),'mismatch',sum(v for (o,e,a),v in c.items() if e!=a))
for k,v in c.most_common(): print(k,v)
print('examples');
for x in examples: print(x)
