const r = await tools.exec_command({cmd:"python3 - <<'PY'
import pickle, numpy as np
from pathlib import Path
p=Path('/app/converted_data.pkl')
with p.open('rb') as f: d=pickle.load(f)
issues=[]
for s,(nn,ii,oo,ri,info) in enumerate(zip(d['neural'],d['input'],d['output'],d['brain_region_idx'],d['metadata']['session_info'])):
    n=len(nn); ids=np.asarray(info['retained_source_trial_indices_zero_based'])
    if not (len(ii)==len(oo)==n==len(ids)): issues.append((s,'lengths'))
    if not (np.all(np.diff(ids)>0) and ids.min()>=info['ephys_first_source_trial_index_zero_based'] and ids.max()<=info['ephys_last_source_trial_index_zero_based']): issues.append((s,'source_ids'))
    if len(ri)!=nn[0].shape[0] or np.any(np.asarray(ri)<0) or np.any(np.asarray(ri)>=len(d['brain_regions'])): issues.append((s,'regions'))
    for j,(a,x,y) in enumerate(zip(nn,ii,oo)):
        if a.shape!=(len(ri),80) or x.shape!=(2,80) or y.shape!=(4,80): issues.append((s,j,'shape'))
        if not np.isfinite(a).all() or not np.isfinite(x).all() or not np.isfinite(y).all(): issues.append((s,j,'nonfinite'))
        if np.any(a<0) or not np.allclose(a/20,np.rint(a/20)): issues.append((s,j,'rate_lattice'))
        if not set(np.unique(x[1])).issubset({0.,1.}): issues.append((s,j,'stim_codes'))
        if not set(np.unique(y[0])).issubset({0,1,2}) or not set(np.unique(y[1])).issubset({0,1,2}) or not set(np.unique(y[2])).issubset({0,1}) or not set(np.unique(y[3])).issubset({0,1,2,3}): issues.append((s,j,'output_codes'))
        if not (np.all(y[0]==y[0,0]) and np.all(y[1]==y[1,0]) and np.all(y[2]==y[2,0])): issues.append((s,j,'trial_label_constant'))
print('sessions',len(d['neural']),'trials',sum(map(len,d['neural'])),'neurons',sum(len(x) for x in d['brain_region_idx']))
print('first_center,last_center',d['metadata']['time_bin_centers_seconds'][0],d['metadata']['time_bin_centers_seconds'][-1])
print('minimum retained trials/session',min(map(len,d['neural'])))
print('audit issues',len(issues),issues[:10])
assert not issues
print('ALL WHOLE-DATA EDGE/SHAPE CHECKS PASSED')
PY","workdir":"/app","yield_time_ms":30000,"max_output_tokens":5000}); text(r.output);

